 function parseArg<T>(schema: z.ZodType<T>, value: unknown, name: string): T {
   const parsed = schema.safeParse(value);
   if (!parsed.success) {
     throw new ReqflowError("invalid_input", `Invalid ${name}`, parsed.error.issues);
   }
   return parsed.data;
